const r = await api.get("/customers");
const list = Array.isArray(r) ? r : (r.items || r.data || r.customers || []);
console.log(Array.isArray(r) ? "array" : Object.keys(r));
if (list.length) console.log(Object.keys(list[0]));
console.log("count", list.length);

const r = await api.get("/customers");
const list = r.items;
const nov = list.filter(c => {
  if (!c.birth_date) return false;
  const m = String(c.birth_date).match(/^\d{4}-(\d{2})/) || String(c.birth_date).match(/(\d{1,2})월/);
  if (m) return Number(m[1]) === 11;
  const d = new Date(c.birth_date);
  return !isNaN(d) && d.getMonth() === 10;
});
return { total_items: list.length, api_count: r.count, nov_count: nov.length, missing_birth: list.filter(c => !c.birth_date).length, sample_format: list.slice(0,3).map(c => String(c.birth_date).replace(/\d/g,"9")) };

